oblique(){change(()=>{if(style().kind!=='upright')throw Error("Selecione um estilo reto para criar seu oblíquo, identificado separadamente.");if(P.styles.length>=LIMIT.styles)throw Error("Limite de 24 estilos");const source=style(),s=clone(source);s.id=source.id+'-oblique-'+Date.now();s.name=source.name.replace(' Italic','')+' Oblique';s.kind='oblique';s.params.angle=num('italicAngle');s.masterApproved=false;s.relationship='independent';for(const g of Object.values(s.glyphs)){g.contours=quantize(mapContours(g.contours,(x,y)=>[x+Math.tan(s.params.angle*Math.PI/180)*y,y]));for(const pt of Object.values(g.anchors))pt[0]+=Math.tan(s.params.angle*Math.PI/180)*pt[1];g.status='candidate';g.locked=false;g.relationship='oblique proposal';}P.styles.push(s);styleId=s.id},"Oblíquo criado e identificado separadamente. Não é um itálico estrutural.");},
